def age_education_housing_profile(df):
    import pandas as pd
    import numpy as np

    result = df[['row_id']].copy()

    # 基于领域知识：
    # IND_09: 教育水平 - 高等教育正相关(tertiary 15.0%, secondary 10.6%, primary 8.6%)
    # IND_05: 无住房贷款 - housing=no 认购概率更高(16.7% vs 7.7%)
    # EXP_06: 关键特征交互 - age-job交互
    # 探索数据显示 age * education * housing 交互效应极强：
    # <30 + tertiary + no: 31.7% (年轻高学历无房贷)
    # 50+ + primary + yes: 5.0% (年长低学历有房贷)
    # 核心思想：年龄反映生命周期阶段，教育反映收入潜力，
    # 住房贷款反映财务负担，三者组合刻画完整经济画像

    age = df['age'].values
    education = df['education'].values
    housing = df['housing'].values

    n = len(df)
    scores = np.zeros(n, dtype=float)

    for i in range(n):
        a = age[i]
        e = education[i]
        h = housing[i]

        # 步骤1: 年龄阶段
        if a < 30:
            age_stage = 'young'
        elif a < 50:
            age_stage = 'mid'
        else:
            age_stage = 'senior'

        # 步骤2: 基于 age+education+housing 的评分
        # 使用探索数据的转化率模式
        if age_stage == 'young':
            if h == 'no':
                if e == 'tertiary':
                    score = 3.0  # 31.7% - 年轻高学历无房贷
                elif e == 'secondary':
                    score = 2.5  # 26.7% - 年轻中等学历无房贷
                elif e == 'unknown':
                    score = 3.0  # 33.1% - 年轻未知学历无房贷
                else:  # primary
                    score = 2.0  # 22.9% - 年轻低学历无房贷
            else:  # housing == 'yes'
                if e == 'tertiary':
                    score = 1.0  # 12.7%
                elif e == 'secondary':
                    score = 0.5  # 8.9%
                else:
                    score = 0.0  # 6.2%
        elif age_stage == 'mid':
            if h == 'no':
                if e == 'tertiary':
                    score = 1.5  # 18.3%
                elif e == 'secondary':
                    score = 1.0  # 11.8%
                elif e == 'unknown':
                    score = 1.0  # 15.6%
                else:  # primary
                    score = 0.0  # 6.2%
            else:  # housing == 'yes'
                score = -0.5  # 所有中年有房贷都低 (~7%)
        else:  # senior
            if h == 'no':
                if e == 'tertiary':
                    score = 1.5  # 19.4%
                elif e == 'secondary':
                    score = 1.5  # 17.6%
                elif e == 'unknown':
                    score = 1.5  # 17.5%
                else:  # primary
                    score = 1.0  # 16.3%
            else:  # housing == 'yes'
                if e == 'tertiary':
                    score = 0.5  # 8.6%
                elif e == 'secondary':
                    score = 0.0  # 7.1%
                elif e == 'unknown':
                    score = 0.5  # 9.9%
                else:  # primary
                    score = -0.5  # 5.0%

        scores[i] = score

    result['age_edu_housing'] = scores

    return result[['row_id', 'age_edu_housing']]

def month_previous_breakthrough(df):
    import pandas as pd
    import numpy as np

    result = df[['row_id']].copy()

    month = df['month'].values
    previous = df['previous'].values
    poutcome = df['poutcome'].values
    campaign = df['campaign'].values

    n = len(df)
    scores = np.zeros(n, dtype=float)

    # 月份分类 (IND_04, RULE_003, EXP_08)
    best_months = {'mar', 'sep', 'oct', 'dec'}
    worst_months = {'may', 'jul'}
    mid_months = {'apr', 'jun', 'nov'}
    normal_months = {'jan', 'feb', 'aug'}

    for i in range(n):
        score = 0.0
        m = month[i]
        p = previous[i]
        po = poutcome[i]
        c = campaign[i]

        # 基础月份分
        if m in best_months:
            base = 2.0
        elif m in mid_months:
            base = 0.5
        elif m in normal_months:
            base = 0.0
        else:  # worst
            base = -1.0

        # 突破效应：最差月份中，有历史联系的客户是突破口
        if m in worst_months and p > 0:
            # 淡季突破效应：有历史联系的客户转化率远高于平均水平
            score += 3.0  # 突破加分
            if po == 'success':
                score += 2.0  # 历史成功更是黄金
            elif po == 'failure':
                score += 0.5  # 历史失败但仍有联系
            # campaign<=3 效果更好
            if c <= 3:
                score += 0.5
        elif m in worst_months:
            # 最差月份，无历史联系 - 低分
            score -= 0.5

        # 最佳月份中，历史联系强化
        if m in best_months:
            if p > 0:
                score += 1.5  # 旺季+历史联系
                if po == 'success':
                    score += 1.5  # 历史成功客户在旺季几乎必买
            else:
                score += 0.5  # 旺季即使无历史联系也不错

        # 中等月份
        if m in mid_months or m in normal_months:
            if p > 0:
                score += 1.0
                if po == 'success':
                    score += 1.0

        # 加上月份基础分
        score += base

        scores[i] = score

    result['month_prev_breakthrough'] = scores

    return result[['row_id', 'month_prev_breakthrough']]
